  'executive': ['ceo', 'cto', 'cfo', 'coo', 'cmo', 'cpo', 'chief', 'vp', 'vice president', 'evp', 'svp'],
  'consulting': ['consultant', 'advisor', 'strategist', 'transformation'],
  'healthcare': ['nurse', 'doctor', 'physician', 'clinical', 'medical', 'healthcare', 'patient']
};

const validateTitle = (title, roleFamily) => {
  if (!title || title.trim() === '') return { valid: false, reason: 'Empty title' };
  const titleLower = title.toLowerCase().trim();
  const isOnlyGeneric = GENERIC_TITLES.some(g => titleLower === g.toLowerCase());
  if (isOnlyGeneric) return { valid: false, reason: `Generic title: ${title}` };
  const keywords = ROLE_FAMILY_KEYWORDS[roleFamily] || [];
  if (keywords.length > 0) {
    const hasRoleKeyword = keywords.some(kw => titleLower.includes(kw.toLowerCase()));
    if (!hasRoleKeyword) return { valid: false, reason: `No role match: ${title}` };
  }
  const excludedFamilies = excluded.role_families || [];
  for (const exFamily of excludedFamilies) {
    const exKeywords = ROLE_FAMILY_KEYWORDS[exFamily] || [];
    if (exKeywords.some(kw => titleLower.includes(kw.toLowerCase()))) {
      return { valid: false, reason: `Excluded family: ${exFamily}` };
    }
  }
  return { valid: true, reason: 'Passed' };
};

const titleValidation = apifyParams.currentJobTitles.map(title => ({ title, ...validateTitle(title, roleFamily) }));
const validTitles = titleValidation.filter(t => t.valid).map(t => t.title);
const rejectedTitles = titleValidation.filter(t => !t.valid);

if (validTitles.length === 0) {
  throw new Error(JSON.stringify({
    success: false,
    error_code: 'TITLE_VALIDATION_FAILED',
    message: `No valid job titles for role family: ${roleFamily}`,
    data: { rejected_titles: rejectedTitles }
