const safeParse = (value, defaultValue = null) => {
  if (!value) return defaultValue;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value) || defaultValue; } catch { return defaultValue; }
};
const safeArray = (value) => {
  const parsed = safeParse(value, []);
  return Array.isArray(parsed) ? parsed.filter(v => v != null && v !== '') : [];
};
const safeString = (value) => value ? String(value).trim() : '';
const dedupe = (arr) => [...new Set(arr.filter(Boolean))];

