const mapIndustryToId = (industryName) => {
  const lower = (industryName || '').toLowerCase();
  for (const [key, id] of Object.entries(INDUSTRY_NAME_TO_ID)) {
    if (lower.includes(key)) return id;
  }
  return null;
};

// Extract ALL core roles from a title (handles comma-separated like "CEO, Partner, Co-founder")
const extractCoreRoles = (title) => {
  if (!title) return [];
  const parts = title.split(/[,&]+/);
  const roleMap = {
    'ceo': 'CEO', 'founder': 'Founder', 'co-founder': 'Founder', 'cofounder': 'Founder',
    'owner': 'Owner', 'president': 'President', 'partner': 'Partner',
    'managing director': 'Managing Director', 'director': 'Director',
    'vp': 'VP', 'vice president': 'VP', 'head': 'Head', 'manager': 'Manager',
    'coo': 'COO', 'cto': 'CTO', 'cfo': 'CFO', 'cmo': 'CMO'
  };
  const found = [];
  for (const part of parts) {
    const t = part.trim().toLowerCase();
    for (const [key, label] of Object.entries(roleMap)) {
      if (t.includes(key)) { found.push(label); break; }
    }
  }
  return found.length > 0 ? found : [title.trim()];
};

