    'owner': 'Owner', 'president': 'President', 'partner': 'Partner',
    'managing director': 'Managing Director', 'director': 'Director',
    'vp': 'VP', 'vice president': 'VP', 'head': 'Head', 'manager': 'Manager'
  };
  const found = [];
  for (const part of parts) {
    const t = part.trim().toLowerCase();
    for (const [key, label] of Object.entries(roleMap)) {
      if (t.includes(key)) { found.push(label); break; }
