  }
  return found.length > 0 ? found : [title.trim()];
};

const dedupe = (arr) => [...new Set(arr.filter(Boolean))];

const mapSeniorityIds = (seniorityLevel, years, currentTitle) => {
  const level = (seniorityLevel || '').toLowerCase();
  const title = (currentTitle || '').toLowerCase();
  const yrs = parseInt(years) || 0;
  if (title.match(/\b(ceo|founder|owner|chief|president|cto|cfo|coo|cmo)\b/)) return ['300', '310', '320'];
  if (title.includes('partner')) return ['320'];
  if (title.match(/\b(vp|vice president)\b/)) return ['300', '310'];
  if (title.match(/\b(director|head of)\b/)) return ['220', '300'];
  if (title.match(/\b(manager|supervisor)\b/)) return yrs >= 10 ? ['210', '220'] : ['200', '210'];
  if (title.match(/\b(lead|principal|staff)\b/)) return ['130', '200'];
  if (level.includes('senior') || yrs >= 8) return ['120', '130'];
  if (level.includes('mid') || yrs >= 3) return ['110', '120'];
  return ['110', '120'];
};

const expandSeniorityRange = (base) => {
  const expanded = new Set(base);
  for (const id of base) {
    const n = parseInt(id);
    if (n >= 110) expanded.add(String(n - 10));
    if (n <= 310) expanded.add(String(n + 10));
  }
  return validateSeniorityIds([...expanded]);
};

