  tier: 2, session_id: inputData.session_id, profile_name: inputData.profile_name,
  role_family: inputData.role_family, apify_input: tier2ApifyInput,
  enforced_mandatory_signals: mandatorySignals,
  enforced_excluded_signals: excludedSignals,
  lookalike_anchor: anchor, firmographic_constraints: inputData.firmographic_constraints,
  tier1_profiles: tier1Profiles, accumulated_profiles: tier1Profiles,
  accumulated_count: inputData.accumulated_count || 0, exclude_urls: [...excludeUrls],
  target_count: targetCount, tier_config: inputData.tier_config,
  is_emergency_mode: false, all_job_titles: inputData.all_job_titles || allTitles
}}];

// ============================================================
// CHECK TIER 2 RESULTS & PREPARE FOR TIER 3 DECISION
// Uses dynamic thresholds from target_results_count
// ============================================================

const inputData = $('Build Tier 2 Input').first().json;
const tier2Results = $input.all();

// Extract profiles from Apify response
let tier2Profiles = [];
for (const item of tier2Results) {
  // Handle dataset items format
  if (item.json && item.json.dataset && item.json.dataset.items) {
    tier2Profiles.push(...item.json.dataset.items);
  }
  // Handle direct items array
  else if (item.json && item.json.items) {
    tier2Profiles.push(...item.json.items);
  }
  // Handle array of profiles
  else if (item.json && Array.isArray(item.json)) {
    tier2Profiles.push(...item.json);
  }
  // Handle single profile object
  else if (item.json && item.json.linkedinUrl) {
    tier2Profiles.push(item.json);
  }
}

// Deduplicate within Tier 2 (excluding Tier 1 URLs)
const seen = new Set(inputData.exclude_urls || []);
const uniqueTier2 = tier2Profiles.filter(p => {
  const url = p.linkedinUrl || p.profileUrl || '';
  if (!url || seen.has(url)) return false;
  seen.add(url);
  return true;
});

// Combine with Tier 1 profiles
const allProfiles = [...(inputData.tier1_profiles || []), ...uniqueTier2];
const cumulativeCount = allProfiles.length;

// Use DYNAMIC threshold (85% of target)
const targetCount = inputData.target_count || inputData.tier_config?.target_count || 50;
const tier2Threshold = inputData.tier_config?.tier2_threshold || Math.ceil(targetCount * 0.85);
const needMoreTier3 = cumulativeCount < tier2Threshold;

return [{
  json: {
    ...inputData,
    tier2_results: {
      count: uniqueTier2.length,
      cumulative: cumulativeCount,
      threshold: tier2Threshold,
      met_threshold: !needMoreTier3
    },
    tier2_profiles: uniqueTier2,
    accumulated_profiles: allProfiles,
    accumulated_count: cumulativeCount,
    need_tier3: needMoreTier3,
    exclude_urls: [...seen],
    target_count: targetCount,
    execution_log: {
      tier_2_count: uniqueTier2.length,
      total_count: cumulativeCount,
      target: targetCount,
      threshold: tier2Threshold,
      needs_tier_3: needMoreTier3
    }
  }
}];

// TIER 3: RECALL RECOVERY - STILL INDUSTRY CONSTRAINED (not fully open)
const inputData = $('Check Tier 2 Count').first().json;

const targetCount = inputData.target_count || inputData.tier_config?.target_count || 50;
const accumulatedCount = inputData.accumulated_count || 0;
const remaining = targetCount - accumulatedCount;
const tier3MaxItems = Math.max(20, Math.ceil(remaining * 1.5));  // Overfetch by 50% for final tier

const VALID_SENIORITY_IDS = ['100', '110', '120', '130', '200', '210', '220', '300', '310', '320'];
const validateSeniorityIds = (ids) => ids.filter(id => VALID_SENIORITY_IDS.includes(String(id))).map(String);

const tier1Input = inputData.apify_input || {};
const accumulatedProfiles = inputData.accumulated_profiles || [];
const mandatorySignals = inputData.enforced_mandatory_signals || {};
const excludedSignals = inputData.enforced_excluded_signals || {};
const excludeUrls = new Set(inputData.exclude_urls || []);

const tier2Profiles = inputData.tier2_profiles || [];
tier2Profiles.forEach(p => {
  const url = p.linkedinUrl || p.profileUrl;
  if (url) excludeUrls.add(url);
});

const tier3Seniority = validateSeniorityIds([
  '110', '120', '130',
  '200', '210', '220',
  '300', '310', '320'
]);

const industryKeywords = (mandatorySignals.keywords || []).slice(0, 5);
const excludedKeywords = (excludedSignals.keywords || []).slice(0, 5);

const jobTitles = tier1Input.currentJobTitles || [];
const keywordPart = industryKeywords.slice(0, 4).join(' OR ') || 'recruiting OR staffing OR talent';

const defaultExclusions = ['-finance', '-consulting', '-legal'];
const customExclusions = excludedKeywords.slice(0, 3).map(k => `-${k.toLowerCase().replace(/\s+/g, '')}`);
const allExclusions = [...new Set([...defaultExclusions, ...customExclusions])].join(' ');

const searchQuery = `(${keywordPart}) ${allExclusions}`;

const tier3ApifyInput = {
  searchQuery,
  currentJobTitles: jobTitles.slice(0, 15),
  pastJobTitles: jobTitles.slice(0, 10),
  currentCompanies: [],
  pastCompanies: [],
  industryIds: tier1Input.industryIds || [],
  locations: tier1Input.locations || [],
  seniorityLevelIds: tier3Seniority,
  yearsOfExperienceIds: [],
  schools: [],
  profileLanguages: ['English'],
  profileScraperMode: 'Full',
  maxItems: tier3MaxItems,
  autoQuerySegmentation: false,
  recentlyChangedJobs: false
};

return [{ json: {
  tier: 3, session_id: inputData.session_id, profile_name: inputData.profile_name,
  role_family: inputData.role_family, apify_input: tier3ApifyInput,
  enforced_mandatory_signals: mandatorySignals,
  enforced_excluded_signals: excludedSignals,
  lookalike_anchor: inputData.lookalike_anchor, firmographic_constraints: inputData.firmographic_constraints,
  tier1_profiles: inputData.tier1_profiles || [], tier2_profiles: tier2Profiles,
  accumulated_profiles: [...accumulatedProfiles, ...tier2Profiles],
  accumulated_count: accumulatedCount, exclude_urls: [...excludeUrls],
  target_count: targetCount, tier_config: inputData.tier_config
}}];

// ============================================================
// MERGE ALL TIERS WITH DEDUPLICATION
// Preserves target_count for dynamic limiting
// ============================================================

const allInputs = $input.all();
let inputData = null;
let tier3Results = [];

// Determine which path we came from
for (const item of allInputs) {
  const json = item.json;

  // Check if this is Tier 3 Apify results (dataset format)
  if (json.dataset && json.dataset.items) {
    tier3Results.push(...json.dataset.items);
  }
  // Check if this is Tier 3 Apify results (items format)
  else if (json.items && Array.isArray(json.items)) {
    tier3Results.push(...json.items);
  }
  // Check if this is a profile array
  else if (json.linkedinUrl || (Array.isArray(json) && json[0]?.linkedinUrl)) {
    if (Array.isArray(json)) {
      tier3Results.push(...json);
    } else {
      tier3Results.push(json);
    }
  }
  // Check if this is the context data from previous tier checks
  else if (json.session_id && (json.accumulated_profiles || json.tier1_profiles)) {
    inputData = json;
  }
}

// If no inputData found, try to get it from parent nodes
if (!inputData) {
  try {
    inputData = $('Check Tier 2 Count').first().json;
  } catch (e) {
    try {
      inputData = $('Check Tier 1 Count').first().json;
    } catch (e2) {
      throw new Error('Could not find tier data from any source');
    }
  }
}

// Get context for Build Tier 3 if available
let tier3Context = null;
try {
  tier3Context = $('Build Tier 3 Input').first().json;
} catch (e) {
  // Tier 3 wasn't executed
}

// Get target_count from any available source
const targetCount = inputData.target_count || 
                    tier3Context?.target_count || 
                    inputData.tier_config?.target_count || 
                    50;

// Collect all profiles from all tiers
const tier1Profiles = inputData.tier1_profiles || [];
const tier2Profiles = inputData.tier2_profiles || [];

// If we have tier3 context, use its accumulated_profiles
let accumulatedBefore = [];
if (tier3Context) {
  accumulatedBefore = tier3Context.accumulated_profiles || [];
} else {
  accumulatedBefore = inputData.accumulated_profiles || [...tier1Profiles, ...tier2Profiles];
}

// Process Tier 3 results and deduplicate
const existingUrls = new Set(
  accumulatedBefore.map(p => p.linkedinUrl || p.profileUrl).filter(Boolean)
);

const uniqueTier3 = tier3Results.filter(p => {
  const url = p.linkedinUrl || p.profileUrl || '';
  if (!url || existingUrls.has(url)) return false;
  existingUrls.add(url);
  return true;
});

// Final merge with tier tagging
const allProfiles = [];

// Add Tier 1 profiles with tier tag
for (const p of tier1Profiles) {
  allProfiles.push({ ...p, _tier: 1, _tier_priority: 1 });
}

// Add Tier 2 profiles with tier tag
for (const p of tier2Profiles) {
  allProfiles.push({ ...p, _tier: 2, _tier_priority: 2 });
}

// Add Tier 3 profiles with tier tag
for (const p of uniqueTier3) {
  allProfiles.push({ ...p, _tier: 3, _tier_priority: 3 });
}

// Final deduplication (safety check)
const seen = new Set();
const finalProfiles = allProfiles.filter(p => {
  const url = p.linkedinUrl || p.profileUrl || '';
  if (!url || seen.has(url)) return false;
  seen.add(url);
  return true;
});

// Summary statistics
const tierBreakdown = {
  tier1: tier1Profiles.length,
  tier2: tier2Profiles.length,
  tier3: uniqueTier3.length,
  total: finalProfiles.length
};

// Determine how many tiers were executed
let tiersExecuted = 1;
if (tier2Profiles.length > 0) tiersExecuted = 2;
if (uniqueTier3.length > 0) tiersExecuted = 3;

return [{
  json: {
    session_id: inputData.session_id,
    profile_name: inputData.profile_name,
    role_family: inputData.role_family,
    all_profiles: finalProfiles,
    total_count: finalProfiles.length,
    target_count: targetCount,
    tiers_executed: tiersExecuted,
    tier_breakdown: tierBreakdown,
    tier_results: {
      tier1: inputData.tier1_results || { count: tier1Profiles.length },
      tier2: inputData.tier2_results || { count: tier2Profiles.length },
      tier3: { count: uniqueTier3.length }
    },
    enforced_mandatory_signals: inputData.enforced_mandatory_signals,
    enforced_excluded_signals: inputData.enforced_excluded_signals,
    lookalike_anchor: inputData.lookalike_anchor,
    firmographic_constraints: inputData.firmographic_constraints,
    tier_config: inputData.tier_config
  }
}];

// ============================================================
// ============================================================
// SCORING CONFIGURATION (Tunable)
// ============================================================
const WEIGHTS = {
  INDUSTRY_MATCH: 40,
  TITLE_MATCH: 30,
  TIER_BONUS_1: 5,   // Reduced from 15 (Optimization: Quality over Tier)
  TIER_BONUS_2: 3,
  EXPERIENCE: 10,
  SENIORITY: 10
};

// ============================================================
// PROCESS & SCORE RESULTS - FIXED with STRICT INDUSTRY FILTERING

// ============================================================

const inputData = $('Merge All Tiers').first().json;
const allProfiles = inputData.all_profiles || [];
const anchor = inputData.lookalike_anchor || {};
const mandatorySignals = inputData.enforced_mandatory_signals || {};
const excludedSignals = inputData.enforced_excluded_signals || {};

// DYNAMIC TARGET from session
const targetCount = inputData.target_count || inputData.tier_config?.target_count || 50;
const tiersExecuted = inputData.tiers_executed || 1;

// ============================================================
// HELPER FUNCTIONS
// ============================================================

const normalizeString = (str) => {
  if (!str) return '';
  return String(str).toLowerCase().trim();
};

// ============================================================
// STRICT INDUSTRY FILTER - MANDATORY CHECK
// ============================================================

const isIndustryMatch = (candidateIndustry, requiredIndustries, requiredKeywords) => {
  if (!candidateIndustry) return false;

  const candInd = normalizeString(candidateIndustry);

  // Check against required industries
  const industries = (requiredIndustries || []).map(normalizeString);
  for (const reqInd of industries) {
    if (candInd.includes(reqInd) || reqInd.includes(candInd)) {
      return true;
    }
  }

  // Check against required keywords (for industry matching)
  const keywords = (requiredKeywords || []).map(normalizeString);
  for (const kw of keywords) {
    if (candInd.includes(kw)) {
      return true;
    }
  }

  return false;
};

const isExcludedIndustry = (candidateIndustry, excludedIndustries, excludedKeywords) => {
  if (!candidateIndustry) return false;

  const candInd = normalizeString(candidateIndustry);

  // Check excluded industries
  const industries = (excludedIndustries || []).map(normalizeString);
  for (const excInd of industries) {
    if (candInd.includes(excInd)) {
      return true;
    }
  }

  // Check excluded keywords
  const keywords = (excludedKeywords || []).map(normalizeString);
  for (const kw of keywords) {
    if (candInd.includes(kw)) {
      return true;
    }
  }

  return false;
};

const hasTitleKeywordMatch = (candidateTitle, requiredKeywords) => {
  if (!candidateTitle || !requiredKeywords?.length) return true; // No filter if no keywords

  const titleLower = normalizeString(candidateTitle);
  const keywords = requiredKeywords.map(normalizeString);

  // At least one keyword must be in title
  return keywords.some(kw => titleLower.includes(kw));
};

// ============================================================
// STRICT FILTER FUNCTION - APPLIED BEFORE SCORING
// ============================================================

const strictFilter = (candidate) => {
  const requiredIndustries = mandatorySignals.industries || [];
  const requiredKeywords = mandatorySignals.keywords || [];
  const excludedIndustries = excludedSignals.industries || [];
  const excludedKeywords = excludedSignals.keywords || [];

  // Get candidate's industry
  const candidateIndustry = candidate.industry ||
                           candidate.currentCompanyIndustry ||
                           candidate.current_company_industry || '';

  // Get candidate's title
  const candidateTitle = candidate.currentTitle ||
                        candidate.current_title ||
                        candidate.headline || '';

  // RULE 1: If we have required industries, candidate MUST match
  if (requiredIndustries.length > 0) {
    const industryMatch = isIndustryMatch(candidateIndustry, requiredIndustries, requiredKeywords);

    // If industry field is empty, check title for industry keywords
    if (!candidateIndustry) {
      const titleHasIndustry = requiredKeywords.some(kw =>
        normalizeString(candidateTitle).includes(normalizeString(kw))
      );
      if (!titleHasIndustry) {
        return { pass: false, reason: 'no_industry_match' };
      }
    } else if (!industryMatch) {
      return { pass: false, reason: 'industry_mismatch' };
    }
  }

  // RULE 2: Check excluded industries
  if (excludedIndustries.length > 0) {
    if (isExcludedIndustry(candidateIndustry, excludedIndustries, excludedKeywords)) {
      return { pass: false, reason: 'excluded_industry' };
    }
  }

  // RULE 3: Title must have some relevance (at least one keyword match)
  if (requiredKeywords.length >= 3) {
    const hasRelevantTitle = hasTitleKeywordMatch(candidateTitle, requiredKeywords.slice(0, 5));
    if (!hasRelevantTitle) {
      return { pass: false, reason: 'no_title_relevance' };
    }
  }

  return { pass: true, reason: 'passed' };
};

// ============================================================
// SCORING FUNCTIONS
// ============================================================

const calculateTitleSimilarity = (profileTitle, anchorTitle, mandatoryTitles) => {
  if (!profileTitle) return 0;
  const pTitle = normalizeString(profileTitle);
  const aTitle = normalizeString(anchorTitle);

  let score = 0;

  // Exact match with anchor
  if (pTitle === aTitle) {
    score += 30;
  }
  // Partial match with anchor
  else if (pTitle.includes(aTitle) || aTitle.includes(pTitle)) {
    score += 20;
  }
  // Word overlap with anchor
  else {
    const pWords = new Set(pTitle.split(/\s+/));
    const aWords = new Set(aTitle.split(/\s+/));
    const overlap = [...pWords].filter(w => aWords.has(w) && w.length > 2).length;
    score += Math.min(overlap * 5, 15);
  }

  // Check mandatory titles
  const titles = mandatoryTitles || [];
  for (const t of titles) {
    if (pTitle.includes(normalizeString(t))) {
      score += 10;
      break;
    }
  }

  return score;
};

const calculateIndustrySimilarity = (profileIndustry, anchorIndustries, mandatoryIndustries) => {
  if (!profileIndustry) return 0;
  const pInd = normalizeString(profileIndustry);

  let score = 0;

  // Check anchor industries - INCREASED WEIGHT
  const aIndustries = (anchorIndustries || []).map(normalizeString);
  for (const aInd of aIndustries) {
    if (pInd === aInd) {
      score += WEIGHTS.INDUSTRY_MATCH;
      break;
    } else if (pInd.includes(aInd) || aInd.includes(pInd)) {
      score += WEIGHTS.TITLE_MATCH;
      break;
    }
  }

  // Check mandatory industries - INCREASED WEIGHT
  const mIndustries = (mandatoryIndustries || []).map(normalizeString);
  for (const mInd of mIndustries) {
    if (pInd.includes(mInd)) {
      score += 20;  // INCREASED from 5
      break;
    }
  }

  return score;
};

const calculateExperienceScore = (yearsExperience) => {
  const years = parseInt(yearsExperience) || 0;
  if (years >= 15) return 10;  // REDUCED from 15
  if (years >= 10) return 8;
  if (years >= 7) return 6;
  if (years >= 5) return 5;
  if (years >= 3) return 3;
  return 2;
};

const calculateSeniorityScore = (seniorityLevel) => {
  const level = normalizeString(seniorityLevel);
  if (level.includes('executive') || level.includes('c-level') || level.includes('chief')) return 10;
  if (level.includes('director') || level.includes('vp') || level.includes('head')) return 8;
  if (level.includes('senior') || level.includes('manager')) return 6;
  if (level.includes('mid') || level.includes('lead')) return 4;
  return 2;
};

const calculateTierBonus = (tier) => {
  // Tier 1 profiles get highest priority
  if (tier === 1) return 15;  // REDUCED from 20
  if (tier === 2) return 8;
  return 0;
};

// ============================================================
// PROCESS ALL PROFILES
// ============================================================

// STEP 1: Apply strict filter FIRST
const filteredProfiles = [];
const rejectedProfiles = {
  no_industry_match: 0,
  industry_mismatch: 0,
  excluded_industry: 0,
  no_title_relevance: 0
};

for (const profile of allProfiles) {
  const filterResult = strictFilter(profile);
  if (filterResult.pass) {
    filteredProfiles.push(profile);
  } else {
    rejectedProfiles[filterResult.reason] = (rejectedProfiles[filterResult.reason] || 0) + 1;
  }
}

// STEP 2: Score remaining profiles
const scoredProfiles = filteredProfiles.map(profile => {
  const titleScore = calculateTitleSimilarity(
    profile.currentTitle || profile.headline,
    anchor.currentTitle,
    mandatorySignals.job_titles
  );

  const industryScore = calculateIndustrySimilarity(
    profile.industry || profile.currentCompanyIndustry,
    anchor.industries,
    mandatorySignals.industries
  );

  const experienceScore = calculateExperienceScore(profile.yearsOfExperience);
  const seniorityScore = calculateSeniorityScore(profile.seniorityLevel);
  const tierBonus = calculateTierBonus(profile._tier);

  const totalScore = titleScore + industryScore + experienceScore + seniorityScore + tierBonus;

  return {
    ...profile,
    _similarity_score: totalScore,
    _score_breakdown: {
      title: titleScore,
      industry: industryScore,
      experience: experienceScore,
      seniority: seniorityScore,
      tier_bonus: tierBonus
    }
  };
});

// Sort by score descending
const sortedProfiles = scoredProfiles.sort((a, b) => b._similarity_score - a._similarity_score);

// DYNAMIC: Limit to target_count
const finalProfiles = sortedProfiles.slice(0, targetCount);

// Calculate quality breakdown - RAISED THRESHOLDS
const excellentMatches = finalProfiles.filter(p => p._similarity_score >= 80).length;
const strongMatches = finalProfiles.filter(p => p._similarity_score >= 60 && p._similarity_score < 80).length;
const moderateMatches = finalProfiles.filter(p => p._similarity_score >= 40 && p._similarity_score < 60).length;

// Calculate statistics
const stats = {
  total_raw: allProfiles.length,
  total_after_filter: filteredProfiles.length,
  final_count: finalProfiles.length,
  target_count: targetCount,
  target_met: finalProfiles.length >= targetCount,
  filter_rejection_rate: allProfiles.length > 0
    ? Math.round((1 - filteredProfiles.length / allProfiles.length) * 100)
    : 0,
  rejection_breakdown: rejectedProfiles,
  avg_score: finalProfiles.length > 0
    ? Math.round(finalProfiles.reduce((sum, p) => sum + p._similarity_score, 0) / finalProfiles.length)
    : 0,
  max_score: finalProfiles.length > 0 ? finalProfiles[0]._similarity_score : 0,
  min_score: finalProfiles.length > 0 ? finalProfiles[finalProfiles.length - 1]._similarity_score : 0,
  quality_breakdown: {
    excellent: excellentMatches,
    strong: strongMatches,
    moderate: moderateMatches
  },
  tier_distribution: {
    tier1: finalProfiles.filter(p => p._tier === 1).length,
    tier2: finalProfiles.filter(p => p._tier === 2).length,
    tier3: finalProfiles.filter(p => p._tier === 3).length
  },
  tiers_executed: tiersExecuted
};

return [{
  json: {
    session_id: inputData.session_id,
    profile_name: inputData.profile_name,
    role_family: inputData.role_family,
    scored_profiles: finalProfiles,
    scoring_stats: stats,
    target_count: targetCount,
    target_met: finalProfiles.length >= targetCount,
    tiers_executed: tiersExecuted,
    tier_breakdown: inputData.tier_breakdown,
    tier_results: inputData.tier_results,
    enforced_mandatory_signals: inputData.enforced_mandatory_signals,
    enforced_excluded_signals: inputData.enforced_excluded_signals,
    lookalike_anchor: inputData.lookalike_anchor,
    firmographic_constraints: inputData.firmographic_constraints
  }
}];

// SAVE LOOKALIKE RESULTS - Prepare for Database & Response
const inputData = $('Process & Score Results').first().json;
const scoredProfiles = inputData.scored_profiles || [];
const sessionId = inputData.session_id;
const targetCount = inputData.target_count || 50;
const targetMet = inputData.target_met || false;
const tiersExecuted = inputData.tiers_executed || 1;
const scoringStats = inputData.scoring_stats || {};

// PREPARE CANDIDATE PROFILES FOR BULK INSERT
const candidateProfiles = scoredProfiles.map(profile => {
  const name = profile.fullName || `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || profile.name || 'Unknown';
  const linkedinUrl = profile.linkedinUrl || profile.linkedin_url || '';
  const score = profile._similarity_score || 0;
  let matchQuality = 'weak';
  if (score >= 80) matchQuality = 'excellent';
  else if (score >= 65) matchQuality = 'strong';
  else if (score >= 50) matchQuality = 'good';
  else if (score >= 35) matchQuality = 'moderate';

  return {
    session_id: sessionId,
    linkedin_url: linkedinUrl,
    name: name,
    photo_url: profile.profilePicture || profile.photo_url || profile.photoUrl || null,
    headline: profile.headline || profile.tagline || null,
    current_title: profile.currentTitle || profile.position || profile.headline?.split(' at ')[0] || null,
    current_company: profile.companyName || profile.currentCompany || profile.currentPosition?.[0]?.companyName || profile.headline?.split(' at ')[1] || null,
    location: typeof profile.location === 'object'
      ? (profile.location?.parsed?.text || profile.location?.linkedinText || JSON.stringify(profile.location))
      : (profile.location || null),
    seniority_level: profile.seniorityLevel || null,
    years_experience: parseInt(profile.yearsOfExperience) || 0,
    top_skills: JSON.stringify(profile.skills || profile.topSkills || []),
    education: JSON.stringify(profile.education || profile.educations || []),
    work_history: JSON.stringify(profile.positions || profile.workHistory || profile.experience || []),
    profile_completeness: profile.profileCompleteness || 0,
    similarity_score: score,
    match_quality: matchQuality,
    match_reasons: JSON.stringify(profile._score_breakdown || {}),
    profile_data: JSON.stringify(profile),
    // FIX: Add metadata fields that were missing
    tier_source: profile._tier || null,
    scrape_run_id: sessionId,
    batch_number: 1
  };
}).filter(p => p.linkedin_url && p.name !== 'Unknown');

// PREPARE CANDIDATE PREVIEW (Top 20 for response)
const candidatePreview = scoredProfiles.slice(0, 20).map(profile => ({
  name: profile.fullName || `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || profile.name || 'Unknown',
  title: profile.headline || profile.currentTitle || profile.occupation || '',
  company: profile.companyName || profile.currentCompany || profile.currentPosition?.[0]?.companyName || '',
  location: profile.location?.parsed?.text || profile.location?.linkedinText || profile.location || '',
  linkedin_url: profile.linkedinUrl || profile.linkedin_url || '',
  photo_url: profile.profilePicture || profile.photo_url || '',
  similarity_score: profile._similarity_score,
  score_breakdown: profile._score_breakdown,
  tier: profile._tier,
  seniority: profile.seniorityLevel || '',
  experience_years: profile.yearsOfExperience || 0
})).filter(c => c.name && c.name !== 'Unknown');

const strongMatchesCount = candidateProfiles.filter(p => p.match_quality === 'excellent' || p.match_quality === 'strong').length;

return [{
  json: {
    session_id: sessionId,
    profile_name: inputData.profile_name,
    role_family: inputData.role_family,
    lookalike_results: JSON.stringify(candidateProfiles.slice(0, 100)),
    results_count: candidateProfiles.length,
    strong_matches_count: strongMatchesCount,
    candidate_profiles: candidateProfiles,
    profiles_to_save: candidateProfiles.length,
    response_data: {
      success: true,
      message: `3-Tier Progressive Search completed. Found ${scoredProfiles.length} of ${targetCount} requested profiles.`,
      data: {
        session_id: sessionId,
        profile_name: inputData.profile_name,
        step: 4,
        status: 'completed',
        role_family: inputData.role_family,
        total_results: candidateProfiles.length,
        target_results: targetCount,
        target_met: targetMet,
        tiers_executed: tiersExecuted,
        profiles_saved: candidateProfiles.length,
        strong_matches: strongMatchesCount,
        average_score: scoringStats.avg_score || 0,
        search_results: {
          total_qualified: candidateProfiles.length,
          quality_breakdown: scoringStats.quality_breakdown,
          tier_distribution: scoringStats.tier_distribution,
          avg_similarity_score: scoringStats.avg_score,
          candidates_preview: candidatePreview
        },
        tier_summary: inputData.tier_results,
        lookalike_anchor: inputData.lookalike_anchor ? {
          title: inputData.lookalike_anchor.currentTitle,
          company: inputData.lookalike_anchor.currentCompany,
          seniority: inputData.lookalike_anchor.seniorityLevel,
          industries: inputData.lookalike_anchor.industries
        } : null,
        firmographic_constraints: inputData.firmographic_constraints,
        enforced_mandatory_signals: inputData.enforced_mandatory_signals
      },
      errors: []
    }
  }
}];

// ============================================================
// FORMAT RESULTS RESPONSE
// Query candidate_profiles and format for API response
// ============================================================

const profiles = $input.all().map(item => item.json);

// Parse JSON fields if stored as strings
const formattedProfiles = profiles.map(p => ({
  id: p.id,
  name: p.name,
  photo_url: p.photo_url,
  headline: p.headline,
  current_title: p.current_title,
  current_company: p.current_company,
  location: p.location,
  seniority_level: p.seniority_level,
  years_experience: p.years_experience,
  similarity_score: p.similarity_score,
  match_quality: p.match_quality,
  linkedin_url: p.linkedin_url,
  top_skills: typeof p.top_skills === 'string' ? JSON.parse(p.top_skills || '[]') : (p.top_skills || []),
  education: typeof p.education === 'string' ? JSON.parse(p.education || '[]') : (p.education || []),
  work_history: typeof p.work_history === 'string' ? JSON.parse(p.work_history || '[]') : (p.work_history || []),
  created_at: p.created_at
}));

// Sort by similarity score descending
formattedProfiles.sort((a, b) => (b.similarity_score || 0) - (a.similarity_score || 0));

return [{
  json: {
    success: true,
    message: `Retrieved ${formattedProfiles.length} candidate profiles`,
    data: {
      results: formattedProfiles,
      total_count: formattedProfiles.length,
      strong_matches: formattedProfiles.filter(p => p.match_quality === 'strong').length,
      good_matches: formattedProfiles.filter(p => p.match_quality === 'good').length
    }
  }
}];

// ============================================================
// FORMAT STATUS RESPONSE
// Return session scrape status
// ============================================================

const session = $input.first().json;

const statusMap = {
  'pending': 'Waiting to start',
  'in_progress': 'Scraping in progress',
  'completed': 'Scraping completed',
  'failed': 'Scraping failed'
};

return [{
  json: {
    success: true,
    message: statusMap[session.scrape_status] || statusMap[session.status] || 'Unknown status',
    data: {
      session_id: session.session_id,
      status: session.status,
      scrape_status: session.scrape_status || session.status,
      current_phase: session.current_phase,
      current_step: session.current_step,
      results_count: session.results_count || 0,
      strong_matches_count: session.strong_matches_count || 0,
      target_results_count: session.target_results_count || 50,
      progress_percent: session.results_count && session.target_results_count 
        ? Math.min(100, Math.round((session.results_count / session.target_results_count) * 100)) 
        : 0,
      created_at: session.created_at,
      updated_at: session.updated_at
    }
  }
}];

// ============================================================
// SPLIT CANDIDATE PROFILES FOR BULK INSERT
// Output each profile as individual item for Supabase insert
// ============================================================

const inputData = $('Save Lookalike Results').first().json;
const profiles = inputData.candidate_profiles || [];

if (profiles.length === 0) {
  return [{ json: { skip: true, message: 'No profiles to insert' } }];
}

// Return each profile as a separate item
return profiles.map(profile => ({
  json: {
    ...profile,
    // Pass through session data for later nodes
    _session_id: inputData.session_id,
    _results_count: inputData.results_count,
    _strong_matches_count: inputData.strong_matches_count
  }
}));

// ============================================================
// COLLECT INSERT RESULTS
// Aggregate profile insert results and prepare for session update
// ============================================================

const allResults = $input.all();
let insertedCount = 0;
let failedCount = 0;
let sessionId = '';
let resultsCount = 0;
let strongMatchesCount = 0;

for (const item of allResults) {
  const json = item.json;

  // Track session data from first item
  if (!sessionId && json._session_id) {
    sessionId = json._session_id;
    resultsCount = json._results_count || 0;
    strongMatchesCount = json._strong_matches_count || 0;
  }

  // Check if insert succeeded
  if (json.id) {
    insertedCount++;
  } else if (json.error || json.skip) {
    failedCount++;
  } else {
    // Assume success if no error field
    insertedCount++;
  }
}

// Get data from Save Lookalike Results if not found
if (!sessionId) {
  try {
    const saveResults = $('Save Lookalike Results').first().json;
    sessionId = saveResults.session_id;
    resultsCount = saveResults.results_count;
    strongMatchesCount = saveResults.strong_matches_count;
  } catch (e) {
    // Use defaults
    resultsCount = insertedCount;
  }
}

return [{
  json: {
    session_id: sessionId,
    profiles_inserted: insertedCount,
    profiles_failed: failedCount,
    results_count: resultsCount || insertedCount,
    strong_matches_count: strongMatchesCount,
    insert_summary: {
      total_attempted: allResults.length,
      successful: insertedCount,
      failed: failedCount
    }
  }
}];

const body = $input.first().json;

if (!body.linkedin_url) {
  throw new Error('linkedin_url is required for email reveal');
}
if (!body.profile_id) {
  throw new Error('profile_id is required for email reveal');
}
if (!body.linkedin_url.includes('linkedin.com')) {
  throw new Error('Invalid LinkedIn URL format');
}

return [{
  json: {
    linkedin_url: body.linkedin_url,
    profile_id: body.profile_id,
    session_id: body.session_id || null
  }
}];

const result = $input.first().json;
const profileId = $('Validate Email Request').first().json.profile_id;
const sessionId = $('Validate Email Request').first().json.session_id;

const email = result.contact_info?.email
  || result.personal_emails?.[0]
  || result.email
  || result.emails?.[0]
  || null;

const confidence = result.contact_info?.has_email ? 'high' : (email ? 'medium' : 'none');
const source = 'apify_linkedin_detail';

if (!email) {
  return [{
    json: {
      success: false,
      profile_id: profileId,
      session_id: sessionId,
      email: null,
      confidence: 'none',
      source: source,
      email_found_at: null,
      error: 'Email not found for this LinkedIn profile'
    }
  }];
}

return [{
  json: {
    success: true,
    profile_id: profileId,
    session_id: sessionId,
    email: email,
    confidence: confidence,
    source: source,
    email_found_at: new Date().toISOString(),
    full_name: result.basic_info?.fullname || null
  }
}];

const emailData = $('Parse Email Result').first().json;

return [{
  json: {
    success: emailData.success,
    profile_id: emailData.profile_id,
    email: emailData.email || null,
    confidence: emailData.confidence || 'none',
    source: emailData.source || 'unknown',
    error: emailData.error || null
  }
}];
